import natureIcon from '../../assets/images/category-nature.png';
import walkIcon from '../../assets/images/category-walk.png';
import forestImage from '../../assets/images/seoul-forest.png';

const route = useRoute(); const router = useRouter(); const authStore = useAuthStore(); const menuOpen = ref(false);
