const isLoggedIn = computed(() => authStore.isAuthenticated || isPreview.value);
const categories = [{ label: '역사', image: historyIcon }, { label: '문화·예술', image: cultureIcon }, { label: '자연', image: natureIcon }, { label: '산책', image: walkIcon }];
const go = (name) => { menuOpen.value = false; router.push({ name }); };
